import sys
d=sys.argv[1]; r=lambda f: open(d+"/"+f,encoding="utf8").read()
h=r("src/index.html")
h=h.replace("/*__LIVE_CSS__*/",r("src/live.css")).replace("/*__EDIT_CSS__*/",r("src/editor.css")).replace("/*__EDIT_JS__*/",r("src/editor.js")).replace("/*__REDE_JS__*/",r("src/rede.js")).replace("/*__CEL_JS__*/",r("src/celular.js")).replace("/*__CEL_CSS__*/",r("src/celular.css")).replace("/*__LIVE_JS__*/",r("src/live.js")).replace("/*__QR__*/",r("src/qrcode.js")).replace("/*__REL_CSS__*/",r("src/relat.css")).replace("/*__REF_CSS__*/",r("src/reforco.css")).replace("/*__REF_JS__*/",r("src/reforco.js")).replace("/*__PES_CSS__*/",r("src/pessoas.css")).replace("/*__PES_JS__*/",r("src/pessoas.js")).replace("/*__INT_JS__*/",r("src/integra.js")).replace("/*__INT_CSS__*/",r("src/integra.css")).replace("/*__V10_JS__*/",r("src/v10.js")).replace("/*__V10_CSS__*/",r("src/v10.css")).replace("/*__V11_CSS__*/",r("src/v11.css")).replace("/*__V11_JS__*/",r("src/v11.js")).replace("/*__V12_CSS__*/",r("src/v12.css")).replace("/*__V12_JS__*/",r("src/v12.js")).replace("/*__V13_CSS__*/",r("src/v13.css")).replace("/*__V13_JS__*/",r("src/v13.js")).replace("/*__V14_CSS__*/",r("src/v14.css")).replace("/*__V14_JS__*/",r("src/v14.js")).replace("/*__V15_CSS__*/",r("src/v15.css")).replace("/*__V15_JS__*/",r("src/v15.js")).replace("/*__PDF_JS__*/",r("src/pdf.js").replace("__HELV__",r("helv.json").strip())).replace("/*__REL_JS__*/",r("src/relat.js")).replace("__MODELOS__",r("modelos.json"))
import base64
def ff(fam,arq,peso): return "@font-face{font-family:'%s';font-style:normal;font-weight:%s;font-display:swap;src:url(data:font/woff2;base64,%s) format('woff2')}" % (fam,peso,base64.b64encode(open(d+"/src/fontes/"+arq,"rb").read()).decode())
fontes="/* v1.6.0: letras embutidas (funcionam sem internet) · Fraunces e Source Sans 3, licença SIL OFL 1.1 */\n"+"\n".join([ff("Fraunces","fraunces-latin-600-normal.woff2",600)]+[ff("Source Sans 3","source-sans-3-latin-%d-normal.woff2"%w,w) for w in (400,500,600,700)])
h=h.replace("/*__FONTES__*/",fontes).replace("/*__TOKENS__*/",r("src/efc-tokens.css")).replace("/*__MOV_CSS__*/",r("src/efc-movimento.css")).replace("/*__CASCA_CSS__*/",r("src/casca.css")).replace("/*__PECAS_CSS__*/",r("src/pecas.css")).replace("/*__FLUIDEZ_CSS__*/",r("src/fluidez.css")).replace("/*__MOV_JS__*/",r("src/efc-movimento.js").replace("if (typeof module !== 'undefined' && module.exports) module.exports = Mov;","")).replace("/*__CASCA_JS__*/",r("src/casca.js")).replace("/*__PECAS_JS__*/",r("src/pecas.js")).replace("/*__FLUIDEZ_JS__*/",r("src/fluidez.js"))
import os; os.makedirs(d+"/dist", exist_ok=True)
open(d+"/dist/index.html","w",encoding="utf8").write(h)
